//! The boss, as numbers: every sphere the shoggoth is made of this frame.
//!
//! The boss is nothing but shaded spheres — a writhing mass of lobes, lashing
//! tentacles studded with pale dot-eyes, and a yellow smiley mask that cracks,
//! spirals inward and is swallowed as `reveal` goes 0 -> 1. This module
//! PLACES them: it answers "what does the boss look like at time t" with a
//! list of spheres ([`BossSpheres`]), 20 floats each — exactly the per-instance
//! block web/shoggoth-core.js feeds its instanced draw with. The JS keeps the
//! camera, the shading and the inking; it holds no animation logic.
//!
//! Roadmap step 3 (docs/ARCHITECTURE.md): a port of the placement code that
//! lived in web/shoggoth-core.js, proven against it BEFORE it was deleted:
//! `tests/fixtures/shoggoth_spheres.txt` was captured from that JS (run under
//! Bun with a mock GL) and `matches_the_golden_record` compares every float.
//! To be reproducible bit for bit the maths mirrors the JS's number model:
//! matrices live in f32 storage (its `M4` used `Float32Array`s, so every
//! product was rounded to f32 at each step) while scalars are f64.

/// Floats per sphere: the model's three rows (12), colour rgb + part id (4),
/// accent rgb + emission (4). The `SPHERE` op's arguments, and the instance
/// layout of `instVS` in web/shoggoth-core.js.
pub const SPHERE_FLOATS: usize = 20;

/// Seconds the mask-off takes (`reveal` 0 -> 1): what the inspector's
/// "transition" phase plays, and the sim's `BOSS_MASK_OFF_SECS`.
pub const MASK_OFF_SECS: f32 = crate::systems::boss::BOSS_MASK_OFF_SECS;

/// What the boss is doing, as the `SHOGGOTH` draw call describes it.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct BossPose {
    /// The continuous animation clock, seconds.
    pub time: f32,
    /// Mask-off progress: 0 = mask intact, 1 = raw enraged form.
    pub reveal: f32,
    /// Where the mask leans (radians, screen convention). `None` = the wander
    /// behaviour's own heading (the inspector's standalone preview).
    pub heading: Option<f32>,
    /// 0..1, how flat toward the camera the mask tilts. `None` = the wander
    /// behaviour's "stop and look up" beats — what the GAME uses.
    pub look_up: Option<f32>,
    /// Drift around the tile with the wander behaviour (preview only; the
    /// game places the boss itself).
    pub wander: bool,
}

/// The frame's spheres, in submission order. Spheres `[0, mask_at)` are the
/// body (drawn with the depth test ON); `[mask_at, count)` are the mask
/// assembly, drawn with it OFF so the mask always sits over the lobes.
#[derive(Debug, Clone, PartialEq)]
pub struct BossSpheres {
    pub data: Vec<f32>,
    pub mask_at: usize,
}

impl BossSpheres {
    pub fn count(&self) -> usize {
        self.data.len() / SPHERE_FLOATS
    }

    pub fn sphere(&self, i: usize) -> &[f32] {
        &self.data[i * SPHERE_FLOATS..(i + 1) * SPHERE_FLOATS]
    }
}

// ---- the palette (the boss is not recoloured) -----------------------------
type Rgb = [f64; 3];
const C_BODY: Rgb = [0.11, 0.14, 0.13]; // dark flesh
const C_BODYA: Rgb = [0.17, 0.22, 0.19]; // its top-lit accent
const C_PURPLE: Rgb = [0.14, 0.10, 0.17]; // bruised purple lobes
const C_PURPLEA: Rgb = [0.20, 0.15, 0.24];
const C_TIP: Rgb = [0.34, 0.12, 0.13]; // tentacle tips, wet red
const C_TIPA: Rgb = [0.48, 0.18, 0.17];
const C_MASK: Rgb = [1.00, 0.83, 0.14]; // friendly yellow smiley
const C_INK: Rgb = [0.05, 0.04, 0.02]; // dark features on the mask
const C_YEYE: Rgb = [1.00, 0.95, 0.55]; // pale-yellow dot eyes (raw form)
const C_YHOT: Rgb = [1.00, 1.00, 0.86]; // hot core of the dot

fn clamp01(x: f64) -> f64 {
    if x < 0.0 {
        0.0
    } else if x > 1.0 {
        1.0
    } else {
        x
    }
}
fn smoothstep(a: f64, b: f64, x: f64) -> f64 {
    let t = clamp01((x - a) / (b - a));
    t * t * (3.0 - 2.0 * t)
}
fn ease(x: f64) -> f64 {
    smoothstep(0.0, 1.0, x)
}
fn mix(a: f64, b: f64, t: f64) -> f64 {
    a + (b - a) * t
}
fn mix3(a: Rgb, b: Rgb, t: f64) -> Rgb {
    [mix(a[0], b[0], t), mix(a[1], b[1], t), mix(a[2], b[2], t)]
}
/// Deterministic pseudo-random in 0..1.
fn hash(i: f64) -> f64 {
    let s = (i * 127.1 + 0.7).sin() * 43758.5453;
    s - s.floor()
}

// ---- column-major mat4 in f32 STORAGE (the JS `M4`): f64 arithmetic, every
//      stored element rounded to f32 ------------------------------------------
type M4 = [f32; 16];

fn ident() -> M4 {
    let mut m = [0.0f32; 16];
    m[0] = 1.0;
    m[5] = 1.0;
    m[10] = 1.0;
    m[15] = 1.0;
    m
}
fn translate(x: f64, y: f64, z: f64) -> M4 {
    let mut m = ident();
    m[12] = x as f32;
    m[13] = y as f32;
    m[14] = z as f32;
    m
}
fn scale(x: f64, y: f64, z: f64) -> M4 {
    let mut m = ident();
    m[0] = x as f32;
    m[5] = y as f32;
    m[10] = z as f32;
    m
}
fn rot_x(a: f64) -> M4 {
    let (s, c) = a.sin_cos();
    let mut m = ident();
    m[5] = c as f32;
    m[6] = s as f32;
    m[9] = -s as f32;
    m[10] = c as f32;
    m
}
fn rot_y(a: f64) -> M4 {
    let (s, c) = a.sin_cos();
    let mut m = ident();
    m[0] = c as f32;
    m[2] = -s as f32;
    m[8] = s as f32;
    m[10] = c as f32;
    m
}
fn rot_z(a: f64) -> M4 {
    let (s, c) = a.sin_cos();
    let mut m = ident();
    m[0] = c as f32;
    m[1] = s as f32;
    m[4] = -s as f32;
    m[5] = c as f32;
    m
}
/// `a * b`, each element summed left to right in f64, then rounded.
fn mul(a: &M4, b: &M4) -> M4 {
    let mut o = [0.0f32; 16];
    for r in 0..4 {
        for c in 0..4 {
            let v = a[r] as f64 * b[c * 4] as f64
                + a[4 + r] as f64 * b[c * 4 + 1] as f64
                + a[8 + r] as f64 * b[c * 4 + 2] as f64
                + a[12 + r] as f64 * b[c * 4 + 3] as f64;
            o[c * 4 + r] = v as f32;
        }
    }
    o
}

// ---- the wander behaviour (masked phase) ----------------------------------
/// A tiny deterministic state machine, stepped at a fixed 1/60 s: it drifts
/// along a heading, occasionally stops and looks up, then picks a new one.
/// In the GAME only its `look` beat is used (the mask tilting up to stare);
/// the inspector's preview also uses its heading and drift.
#[derive(Debug, Clone, Copy, PartialEq)]
struct Wander {
    x: f64,
    z: f64,
    heading: f64,
    tgt: f64,
    mode: u8,
    mode_t: f64,
    dur: f64,
    look: f64,
    dec: f64,
}

impl Wander {
    fn new() -> Self {
        Wander {
            x: 0.0,
            z: 0.0,
            heading: hash(1.0) * 6.283,
            tgt: hash(1.0) * 6.283,
            mode: 0,
            mode_t: 0.0,
            dur: 3.5 + hash(2.0) * 2.5,
            look: 0.0,
            dec: 1.0,
        }
    }

    fn step(&mut self, dt: f64) {
        use std::f64::consts::PI;
        self.mode_t += dt;
        if self.mode == 0 {
            // drifting: steer smoothly toward the target heading
            let mut d = self.tgt - self.heading;
            while d > PI {
                d -= 6.283;
            }
            while d < -PI {
                d += 6.283;
            }
            self.heading += d * (dt * 1.6).min(1.0);
            let spd = 0.55;
            self.x += self.heading.cos() * spd * dt;
            self.z += self.heading.sin() * spd * dt;
            if self.x.hypot(self.z) > 1.35 {
                // stay in frame: steer back inward
                self.tgt = (-self.z).atan2(-self.x) + (hash(self.dec + 7.0) - 0.5) * 0.8;
            }
            self.look += (0.0 - self.look) * (dt * 3.0).min(1.0);
            if self.mode_t > self.dur {
                self.mode = 1;
                self.mode_t = 0.0;
                self.dur = 1.8 + hash(self.dec + 3.0) * 1.6;
                self.dec += 1.0;
            }
        } else {
            // stopped, looking up
            self.look += (1.0 - self.look) * (dt * 2.6).min(1.0);
            if self.mode_t > self.dur {
                self.mode = 0;
                self.mode_t = 0.0;
                self.dur = 3.2 + hash(self.dec + 3.0) * 2.6;
                self.tgt = self.heading + (hash(self.dec + 5.0) - 0.5) * 3.2;
                self.dec += 1.0;
            }
        }
    }
}

/// The behaviour at time `t`: whole 1/60 s steps from 0, then ONE partial
/// step to land on `t`. A pure function of `t` (the JS cached its state and
/// so depended on the order of the queries; a fresh JS pipeline — what the
/// golden record captured — computes exactly this).
///
/// The whole steps are memoized per thread, so a frame costs O(1) steps while
/// the clock moves forward instead of O(60 t).
fn wander_at(t: f64) -> Wander {
    use std::cell::RefCell;
    thread_local! {
        static WHOLE: RefCell<(Wander, f64)> = RefCell::new((Wander::new(), 0.0));
    }
    const DT: f64 = 1.0 / 60.0;
    WHOLE.with(|cell| {
        let mut whole = cell.borrow_mut();
        if t < whole.1 - 1e-6 {
            *whole = (Wander::new(), 0.0); // the clock went backward: re-simulate
        }
        loop {
            let (state, sim_t) = &mut *whole;
            if *sim_t >= t - 1e-9 {
                return *state;
            }
            let s = DT.min(t - *sim_t);
            if s < DT {
                // the landing step: not kept, the next frame redoes it
                let mut landed = *state;
                landed.step(s);
                return landed;
            }
            state.step(s);
            *sim_t += s;
        }
    })
}

// ---- the spheres ----------------------------------------------------------
struct Builder {
    data: Vec<f32>,
}

impl Builder {
    /// One sphere: `model`'s three rows, then the two colour blocks (M4 is
    /// column-major: row r is m[r], m[4 + r], m[8 + r], m[12 + r]).
    fn sphere(&mut self, m: &M4, col: Rgb, acc: Rgb, id: f64, emis: f64) {
        for r in 0..3 {
            self.data.extend_from_slice(&[m[r], m[4 + r], m[8 + r], m[12 + r]]);
        }
        self.data.extend_from_slice(&[col[0] as f32, col[1] as f32, col[2] as f32, id as f32]);
        self.data.extend_from_slice(&[acc[0] as f32, acc[1] as f32, acc[2] as f32, emis as f32]);
    }

    #[allow(clippy::too_many_arguments)]
    fn blob(&mut self, root: &M4, p: [f64; 3], r: [f64; 3], col: Rgb, acc: Rgb, id: f64, emis: f64) {
        let m = mul(root, &mul(&translate(p[0], p[1], p[2]), &scale(r[0], r[1], r[2])));
        self.sphere(&m, col, acc, id, emis);
    }

    /// THE WRITHING MASS: 1 core + orbiting satellite lobes.
    fn mass(&mut self, root: &M4, time: f64, frantic: bool) {
        const LOBES: usize = 9;
        let core_sq = 1.0 + 0.06 * (time * 0.9).sin();
        self.blob(root, [0.0, 0.0, 0.0], [1.65, 1.35 * core_sq, 1.65], C_BODY, C_BODYA, 0.14, 0.0);
        self.blob(
            root,
            [0.25 * (time * 0.6).sin(), 0.15, -0.2 * (time * 0.5).cos()],
            [1.25, 1.15, 1.3],
            C_PURPLE,
            C_PURPLEA,
            0.22,
            0.0,
        );
        for k in 0..LOBES {
            let kf = k as f64;
            let a = (kf / LOBES as f64) * std::f64::consts::PI * 2.0;
            let spd = 0.4 + hash(kf) * 0.5;
            let ph = hash(kf + 10.0) * 6.28;
            let wob = if frantic { 0.55 } else { 0.28 };
            let rad = 1.15 + hash(kf + 3.0) * 0.5 + (time * spd + ph).sin() * wob;
            let yb = -0.35
                + (time * spd * 1.3 + ph).sin() * (if frantic { 0.5 } else { 0.28 })
                + hash(kf + 7.0) * 0.5;
            let orbit = a + time * (if frantic { 0.5 } else { 0.22 });
            let x = orbit.cos() * rad;
            let z = orbit.sin() * rad;
            let r = 0.62 + hash(kf + 5.0) * 0.45;
            let pr = 1.0 + 0.14 * (time * 1.7 + ph).sin();
            let purple = hash(kf + 2.0) > 0.55;
            self.blob(
                root,
                [x, yb, z],
                [r * pr, r * (0.85 + 0.2 * (time + ph).sin()), r * pr],
                if purple { C_PURPLE } else { C_BODY },
                if purple { C_PURPLEA } else { C_BODYA },
                0.30 + kf * 0.055,
                0.0,
            );
        }
    }

    /// THE SMILEY MASK and its break-up: a ring of wedge shards + a centre cap
    /// plus the ink features. At `reveal` 0 the shards overlap into a clean
    /// dome; as it climbs the shell cracks, then shards and features are
    /// SUCKED INWARD and down into the maw — shrinking, spiralling, darkening
    /// to dead flesh. `mroot` already places the mask on the crown.
    fn mask(&mut self, mroot: &M4, time: f64, reveal: f64) {
        use std::f64::consts::PI;
        let s = ease(clamp01(reveal * 1.05)); // consume progress 0..1
        let jitter = if reveal > 0.02 && reveal < 0.55 { reveal * 0.05 } else { 0.0 };
        let dk = smoothstep(0.42, 1.0, reveal);
        let shard_col = mix3(C_MASK, C_BODY, dk * 0.95);
        let shard_em = 0.85 * (1.0 - smoothstep(0.30, 1.0, reveal));
        let shrink = mix(1.0, 0.06, s); // shards shrink as they are pulled in
        let in_r = 1.0 - s; // the ring radius collapses toward the maw
        let sink = s * 0.6; // a slight downward drift into the maw

        // hairline cracks that appear just before the shell lets go
        if reveal > 0.02 && reveal < 0.5 {
            let ca = smoothstep(0.02, 0.16, reveal) * (1.0 - smoothstep(0.36, 0.5, reveal));
            for c in 0..3 {
                let ang = c as f64 * 1.05 + 0.3;
                let mut m = mul(mroot, &translate(0.0, 0.30, 0.0));
                m = mul(&m, &rot_y(ang));
                m = mul(&m, &scale(1.15 * ca, 0.05, 0.055));
                self.sphere(&m, C_INK, C_INK, 0.58, 0.0);
            }
        }

        // the ring of wedge shards: sucked inward + down while spiralling
        const SH: usize = 6;
        for k in 0..SH {
            let kf = k as f64;
            let dir = if k % 2 == 1 { 1.0 } else { -1.0 };
            let a = (kf / SH as f64) * PI * 2.0;
            let swirl = a + s * 2.4 * dir; // spiral into the maw
            let jx = (time * 23.0 + kf).sin() * jitter;
            let jz = (time * 21.0 + kf).cos() * jitter;
            let px = swirl.cos() * 0.60 * in_r + jx;
            let pz = swirl.sin() * 0.60 * in_r + jz;
            let py = -sink * (0.6 + hash(kf + 41.0) * 0.5);
            let spin = s * (4.0 + hash(kf + 42.0) * 3.0);
            let mut m = translate(px, py, pz);
            m = mul(&m, &rot_z(spin * dir));
            m = mul(&m, &rot_x(spin * 0.6));
            m = mul(&m, &scale(0.62 * shrink, 0.26 * shrink, 0.62 * shrink));
            self.sphere(&mul(mroot, &m), shard_col, shard_col, 0.80 + kf * 0.006, shard_em);
        }
        // the centre cap: shrinks down into the maw
        {
            let mut m = translate(0.0, -sink * 0.8, 0.0);
            m = mul(&m, &rot_x(s * 4.0));
            m = mul(&m, &scale(0.66 * shrink, 0.30 * shrink, 0.66 * shrink));
            self.sphere(&mul(mroot, &m), shard_col, shard_col, 0.79, shard_em);
        }

        // the ink features (two eyes + an upward smile), drawn in toward the centre
        let fy = 0.42;
        let feat = |x: f64, z: f64| -> M4 {
            let mut m = translate(x * in_r, fy - sink, z * in_r);
            m = mul(&m, &rot_z(s * 5.0));
            m = mul(&m, &scale(shrink, shrink, shrink));
            mul(mroot, &m)
        };
        for x in [-0.44, 0.44] {
            self.sphere(&mul(&feat(x, -0.42), &scale(0.20, 0.15, 0.24)), C_INK, C_INK, 0.55, 0.0);
        }
        const N: usize = 7;
        for i in 0..N {
            let tt = (i as f64 / (N - 1) as f64) * 2.0 - 1.0;
            let x = tt * 0.66;
            let z = 0.16 + 0.34 * (1.0 - tt * tt);
            self.sphere(&mul(&feat(x, z), &scale(0.135, 0.12, 0.135)), C_INK, C_INK, 0.55, 0.0);
        }
    }

    /// RAW FORM: pale-yellow glowing dot eyes over the crown.
    fn yellow_eyes(&mut self, root: &M4, time: f64, fade: f64) {
        for i in 0..15 {
            let fi = i as f64;
            let a = fi * 2.399; // golden-angle scatter
            let rr = 0.18 + hash(fi + 30.0) * 0.92; // cluster over the crown
            let x = a.cos() * rr + 0.08 * (time * 1.2 + fi).sin();
            let z = a.sin() * rr * 0.9 + 0.08 * (time * 1.0 + fi).cos();
            let y = 1.35 + hash(fi + 31.0) * 0.65; // up on the crown
            let tw = 0.85 + 0.15 * (time * 2.5 + fi * 1.3).sin().abs(); // gentle twinkle
            // big enough that the yellow core survives the ink outline
            let s = (0.16 + hash(fi + 32.0) * 0.07) * (0.55 + 0.45 * fade);
            self.blob(root, [x, y, z], [s, s, s], C_YEYE, C_YEYE, 0.62 + fi * 0.012, tw * fade);
            let h = s * 0.45;
            self.blob(root, [x, y + 0.03, z], [h, h, h], C_YHOT, C_YHOT, 0.92, fade);
        }
    }

    /// Many chunky lashing tentacles. `grow` scales them in during the
    /// transition (0 = hidden, 1 = full length); `eye_fade` fades in the pale
    /// dot-eyes that stud the arms and tips.
    fn tentacles(&mut self, root: &M4, time: f64, grow: f64, frantic: bool, eye_fade: f64) {
        const T: usize = 11;
        const SEG: usize = 8;
        for k in 0..T {
            let kf = k as f64;
            let a = (kf / T as f64) * std::f64::consts::PI * 2.0 + 0.3;
            let mut m = mul(root, &translate(a.cos() * 1.20, -0.05, a.sin() * 1.20));
            m = mul(&m, &rot_y(-a)); // face outward
            m = mul(&m, &rot_z(-1.05)); // tip the up-axis outward
            let seglen = 0.60 * grow;
            for i in 0..SEG {
                let fi = i as f64;
                let bend = (time * 2.5 + fi * 0.9 + kf * 1.7).sin() * (if frantic { 0.62 } else { 0.4 });
                let sweep = (time * 1.9 + fi * 0.7 + kf * 2.1).cos() * (if frantic { 0.55 } else { 0.35 });
                m = mul(&m, &rot_x(sweep));
                m = mul(&m, &rot_z(bend * 0.5));
                let tp = fi / (SEG - 1) as f64;
                let r = 0.50 * (1.0 - tp * 0.70);
                let seg = mul(&m, &mul(&translate(0.0, seglen * 0.5, 0.0), &scale(r, seglen * 0.62, r)));
                self.sphere(
                    &seg,
                    mix3(C_BODY, C_TIP, tp),
                    mix3(C_BODYA, C_TIPA, tp),
                    0.30 + kf * 0.03 + fi * 0.005,
                    0.0,
                );
                // dot-eyes on the arm: always one at the tip, plus a few scattered along
                if eye_fade > 0.02 && grow > 0.6 && (i == SEG - 1 || hash(kf * 13.0 + fi + 50.0) > 0.62) {
                    let es = (r * 0.75).max(0.13);
                    let tw = 0.82 + 0.18 * (time * 2.6 + kf * 1.3 + fi).sin().abs();
                    self.blob(
                        &m,
                        [0.0, seglen * 0.5, r * 0.85],
                        [es, es, es],
                        C_YEYE,
                        C_YEYE,
                        0.66 + kf * 0.02 + fi * 0.006,
                        tw * eye_fade,
                    );
                    let h = es * 0.45;
                    self.blob(&m, [0.0, seglen * 0.55, r * 0.9], [h, h, h], C_YHOT, C_YHOT, 0.94, eye_fade);
                }
                m = mul(&m, &translate(0.0, seglen, 0.0));
            }
        }
    }
}

/// Every sphere of the boss for one frame.
pub fn boss_spheres(pose: &BossPose) -> BossSpheres {
    let time = pose.time as f64;
    let reveal = clamp01(pose.reveal as f64);

    // behaviour: heading / the look-up beat / drift, unless the caller drives them
    let b = wander_at(time);
    let heading = pose.heading.map_or(b.heading, |h| h as f64);
    let mut look_up = pose.look_up.map_or(b.look, |l| clamp01(l as f64));
    // it rears up to stare as the mask lets go
    if reveal > 0.0 && reveal < 1.0 {
        look_up = look_up.max(1.0 - smoothstep(0.06, 0.32, reveal));
    }
    let drift = if pose.wander { [b.x, b.z] } else { [0.0, 0.0] };

    // the drift eases to centre as it rears up; spin & list ramp in with the raw form
    let dr = 1.0 - ease(reveal);
    let spin = ease(reveal) * 0.32;
    let list = 0.05 + ease(reveal) * 0.07;
    let mut body = translate(drift[0] * dr, 0.0, drift[1] * dr);
    body = mul(&body, &rot_y(time * spin));
    body = mul(&body, &rot_z((time * 0.5).sin() * list));
    body = mul(&body, &rot_x((time * 0.42).cos() * list));

    let frantic = reveal > 0.5;
    let grow = smoothstep(0.12, 0.95, reveal);
    let eye_fade = smoothstep(0.35, 1.0, reveal);

    let mut out = Builder { data: Vec::with_capacity(230 * SPHERE_FLOATS) };
    if grow > 0.02 {
        out.tentacles(&body, time, grow, frantic, eye_fade);
    }
    out.mass(&body, time, frantic);
    if eye_fade > 0.02 {
        out.yellow_eyes(&body, time, eye_fade);
    }

    // the mask / its break-up (skipped once fully gone). Everything from here
    // on is drawn with the depth test OFF, so (a) masked, the mask is ALWAYS
    // in front of the mass / lobes at every heading and (b) during the
    // transition the shards stay visible as they spiral inward.
    let mask_at = out.data.len() / SPHERE_FLOATS;
    if reveal < 0.999 {
        let y_top = 1.55; // ride high on the crown, above the lobes
        let lean = (1.0 - look_up) * 0.34; // lean toward the heading; flat when looking up
        let mut mroot = mul(&body, &translate(0.0, y_top, 0.05));
        // face (the smile side, local +z) toward the heading, then tilt forward
        mroot = mul(&mroot, &rot_y(std::f64::consts::PI / 2.0 - heading));
        mroot = mul(&mroot, &rot_x(lean));
        out.mask(&mroot, time, reveal);
    }
    BossSpheres { data: out.data, mask_at }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn masked(time: f32) -> BossPose {
        BossPose { time, reveal: 0.0, heading: Some(0.7), look_up: None, wander: false }
    }

    /// The golden record: captured from the JS placement code this module
    /// replaced (web/shoggoth-core.js, run under Bun with a mock GL) before it
    /// was deleted. Small frames are recorded whole, big ones every 4th sphere
    /// + the last; the sphere COUNT and the mask split are always checked.
    /// Measured bit-exact when recorded; the tolerance only absorbs a last-bit
    /// `sin` / `cos` difference between platforms' libm.
    #[test]
    fn matches_the_golden_record() {
        let fixture = include_str!("../../tests/fixtures/shoggoth_spheres.txt");
        let mut current: Option<BossSpheres> = None;
        let (mut cases, mut spheres) = (0, 0);
        for line in fixture.lines().filter(|l| !l.starts_with('#') && !l.is_empty()) {
            let f: Vec<&str> = line.split(' ').collect();
            if f[0] == "case" {
                let opt = |s: &str| (s != "-").then(|| s.parse::<f32>().unwrap());
                let pose = BossPose {
                    reveal: f[1].parse().unwrap(),
                    time: f[2].parse().unwrap(),
                    heading: opt(f[3]),
                    look_up: opt(f[4]),
                    wander: f[5] == "1",
                };
                let got = boss_spheres(&pose);
                assert_eq!(got.count(), f[6].parse::<usize>().unwrap(), "sphere count: {line}");
                assert_eq!(got.mask_at, f[7].parse::<usize>().unwrap(), "mask split: {line}");
                current = Some(got);
                cases += 1;
                continue;
            }
            let got = current.as_ref().expect("a case line first");
            let i: usize = f[0].parse().unwrap();
            assert_eq!(f.len(), 1 + SPHERE_FLOATS, "malformed row: {line}");
            for (k, want) in f[1..].iter().enumerate() {
                let want: f32 = want.parse().unwrap();
                let have = got.sphere(i)[k];
                assert!(
                    (have - want).abs() <= 1e-5,
                    "case {cases}, sphere {i}, float {k}: {have}, the golden record says {want}"
                );
            }
            spheres += 1;
        }
        assert!(cases >= 10 && spheres > 300, "truncated fixture: {cases} cases, {spheres} spheres");
    }

    #[test]
    fn the_mask_is_the_depth_off_tail_and_is_gone_when_enraged() {
        let m = boss_spheres(&masked(1.0));
        // masked: the mass (2 + 9 lobes), then 6 shards + cap + 2 eyes + 7 smile dots
        assert_eq!((m.mask_at, m.count()), (11, 27));
        let raw = boss_spheres(&BossPose { reveal: 1.0, ..masked(1.0) });
        assert_eq!(raw.mask_at, raw.count(), "no mask spheres once fully revealed");
        assert!(raw.count() > 150, "the raw form has its tentacles and eyes");
        // mid mask-off: everything at once — the frame the instance buffer is sized for
        let mid = boss_spheres(&BossPose { reveal: 0.7, ..masked(1.0) });
        assert!(mid.mask_at < mid.count() && mid.count() <= 230, "{} spheres", mid.count());
    }

    #[test]
    fn every_float_is_finite_over_the_whole_arc() {
        for r in 0..=20 {
            for t in [0.0f32, 0.4, 3.3, 47.0, 600.0] {
                let s = boss_spheres(&BossPose { reveal: r as f32 / 20.0, ..masked(t) });
                assert_eq!(s.data.len() % SPHERE_FLOATS, 0);
                assert!(s.data.iter().all(|v| v.is_finite()), "reveal {r}/20, t {t}");
            }
        }
    }

    #[test]
    fn the_wander_is_a_pure_function_of_time() {
        // Memoized, but the answer must not depend on the order of the queries
        // (the JS it replaces did — its cache kept the partial landing step).
        let late = wander_at(12.34);
        let _ = wander_at(3.0); // the clock goes backward: re-simulated
        let _ = wander_at(7.77);
        assert_eq!(wander_at(12.34), late);
        // and it does both of its beats within a minute
        let looks: Vec<f64> = (0..600).map(|i| wander_at(i as f64 * 0.1).look).collect();
        assert!(looks.iter().any(|&l| l > 0.9) && looks.iter().any(|&l| l < 0.05));
    }

    #[test]
    fn the_game_gets_the_look_up_beat_without_the_drift() {
        // What render.rs asks for: heading from the sim, look-up from the beat.
        let at = |t: f32| boss_spheres(&masked(t));
        let (a, b) = (at(1.0), at(1.0));
        assert_eq!(a, b, "deterministic");
        // no drift: the core sphere's translation x / z stay 0
        let core = a.sphere(0);
        assert_eq!((core[3], core[11]), (0.0, 0.0));
        let drifting = boss_spheres(&BossPose { wander: true, heading: None, ..masked(9.0) });
        assert!(drifting.sphere(0)[3] != 0.0 || drifting.sphere(0)[11] != 0.0);
    }
